insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules)
values
  ('course-ing-civil', 'Fundamentos de Ingeniería Civil', 'Cómo se diseña y construye el mundo físico que nos rodea: materiales, fuerzas, cimentaciones e infraestructura, explicado desde cero.', 'Eres el Mago, tutor de Fundamentos de Ingeniería Civil en Oliver Academy. Explica conceptos de estructuras y materiales con analogías cotidianas (un puente como una fila de personas repartiendo peso, el concreto como una mezcla de fuerza a compresión) antes de la terminología técnica. Anima al estudiante a fijarse en construcciones reales de su ciudad.', '🏗️', '#f97316', 'Ingeniería', 'Civil', null, false, '[{"id":"civ-01","order":1,"type":"text","title":"¿Qué hace un ingeniero civil?","description":"El alcance de una de las ingenierías más antiguas: de las pirámides a los rascacielos.","content":"<h2>La ingeniería más antigua del mundo</h2><p>Mucho antes de que existiera la palabra \"ingeniero\", ya había personas resolviendo el mismo problema: cómo construir algo que no se caiga. Las pirámides de Egipto, el Coliseo romano, los acueductos — todo eso es <strong>ingeniería civil</strong> sin el nombre todavía.</p><h2>¿Qué diseña un ingeniero civil hoy?</h2><ul><li><strong>Edificaciones:</strong> casas, edificios, rascacielos.</li><li><strong>Infraestructura de transporte:</strong> carreteras, puentes, túneles, vías de tren.</li><li><strong>Infraestructura hidráulica:</strong> presas, sistemas de agua potable y drenaje.</li><li><strong>Geotecnia:</strong> el estudio del suelo bajo todo lo anterior.</li></ul><div class=\"tip\">💡 Casi todo lo que ves cuando sales a la calle — excepto los aparatos electrónicos — pasó por las manos (o los cálculos) de un ingeniero civil.</div><h2>La responsabilidad central: seguridad</h2><p>A diferencia de otros oficios creativos, un error de diseño en ingeniería civil puede costar vidas. Por eso esta disciplina está construida alrededor de <strong>códigos y normas</strong> — reglas mínimas obligatorias, no sugerencias — y de <strong>márgenes de seguridad</strong>: se diseña para resistir mucho más de lo que se espera que necesite soportar en la práctica.</p>","exercises":[{"id":"civ-01-1","type":"challenge","prompt":"Observa un edificio o puente cercano a donde vives. ¿Qué elementos identificas (columnas, vigas, cimentación visible)? Descríbelo y compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es la responsabilidad central que distingue a la ingeniería civil de otras disciplinas creativas?","options":["La velocidad de construcción","La seguridad — un error puede costar vidas","El costo de los materiales","La estética del diseño"],"correctIndex":1},"comments":[]},{"id":"civ-02","order":2,"type":"text","title":"Materiales: concreto, acero y madera","description":"Las propiedades que hacen que un material sirva (o no) para construir.","content":"<h2>Concreto: fuerte a compresión, débil a tensión</h2><p>El <strong>concreto</strong> (cemento + agua + arena + grava) es excelente resistiendo que lo <strong>compriman</strong> (aplastar) pero muy débil resistiendo que lo <strong>estiren</strong> (tensión) — se agrieta fácilmente. Por eso casi nunca se usa solo.</p><div class=\"example\">🧪 <strong>Concreto armado:</strong> se le insertan barras de acero (varillas) DENTRO del concreto antes de que endurezca. El acero es fuerte a tensión, el concreto es fuerte a compresión — juntos se compensan las debilidades del otro.</div><h2>Acero: fuerte en ambas direcciones</h2><p>El <strong>acero</strong> resiste bien tanto compresión como tensión, y es más ligero por unidad de fuerza que soporta que el concreto — por eso los rascacielos más altos usan estructuras de acero, no solo concreto.</p><h2>Madera: renovable, pero variable</h2><p>La <strong>madera</strong> es liviana, renovable y fácil de trabajar, pero sus propiedades varían según el tipo de árbol, la humedad y la dirección de la veta — un ingeniero debe diseñar con más margen de seguridad al usarla.</p><div class=\"warn\">⚠️ Ningún material es \"el mejor\" en abstracto — la elección depende del presupuesto, el clima, la disponibilidad local y qué tipo de fuerzas va a enfrentar la estructura.</div>","exercises":[{"id":"civ-02-1","type":"challenge","prompt":"Explica con tus palabras por qué el concreto casi nunca se usa \"solo\" (sin acero) en una estructura importante. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Por qué se combina acero con concreto en el \"concreto armado\"?","options":["Para que se vea mejor","El acero compensa la debilidad del concreto ante la tensión","Para que sea más barato","El concreto no puede endurecer sin acero"],"correctIndex":1},"comments":[]},{"id":"civ-03","order":3,"type":"text","title":"Fuerzas y estructuras: cargas, tensión y compresión","description":"El vocabulario básico para entender por qué una estructura se sostiene — o no.","content":"<h2>Tipos de carga</h2><p>Una <strong>carga</strong> es cualquier fuerza que una estructura debe soportar. Se dividen en dos grandes grupos: <strong>carga muerta</strong> (el peso propio de la estructura, siempre presente) y <strong>carga viva</strong> (personas, muebles, vehículos, nieve — cambia con el tiempo).</p><h2>Compresión, tensión y flexión</h2><ul><li><strong>Compresión:</strong> algo que empuja/aplasta un elemento (una columna soportando un techo).</li><li><strong>Tensión:</strong> algo que estira un elemento (un cable de un puente colgante).</li><li><strong>Flexión:</strong> una combinación de ambas al mismo tiempo, típica de vigas horizontales (un lado se comprime, el otro se estira).</li></ul><div class=\"example\">🧪 Una <strong>viga</strong> apoyada en sus dos extremos, con peso en medio, se comprime por arriba y se estira por abajo al mismo tiempo — por eso las vigas de concreto llevan el acero concentrado en la parte de abajo, donde ocurre la tensión.</div><h2>Por qué los triángulos son la forma favorita de la ingeniería</h2><p>A diferencia de un rectángulo (que puede deformarse en un paralelogramo bajo fuerza lateral), un <strong>triángulo</strong> es geométricamente rígido — no puede cambiar de forma sin que uno de sus lados cambie de longitud. Por eso las torres, grúas y armaduras de puentes están llenas de triángulos.</p><div class=\"tip\">💡 La próxima vez que veas una torre de transmisión eléctrica o una grúa de construcción, cuenta cuántos triángulos puedes identificar en su estructura.</div>","exercises":[{"id":"civ-03-1","type":"challenge","prompt":"Busca una foto o recuerda una estructura (torre, puente, grúa) con muchos triángulos visibles. ¿Por qué crees que se usó esa forma en vez de rectángulos? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Por qué los ingenieros prefieren triángulos sobre rectángulos en estructuras como torres y puentes?","options":["Los triángulos son más baratos de fabricar","Un triángulo es geométricamente rígido, no se deforma fácilmente","Los rectángulos no soportan ningún peso","Es solo una preferencia estética"],"correctIndex":1},"comments":[]},{"id":"civ-04","order":4,"type":"text","title":"Cimentaciones: el edificio que no ves","description":"Por qué lo más importante de una construcción está enterrado.","content":"<h2>El suelo no es uniforme</h2><p>Antes de construir cualquier cosa, un ingeniero civil debe estudiar el <strong>suelo</strong>: qué tipo de tierra es, qué tan compacta está, si hay agua subterránea, si hay riesgo sísmico. Esto se llama <strong>estudio geotécnico</strong>, y determina qué tipo de cimentación se necesita.</p><h2>Cimentaciones superficiales vs. profundas</h2><p>Cuando el suelo firme está cerca de la superficie, basta con una <strong>cimentación superficial</strong> (zapatas, losas). Cuando el suelo firme está muy profundo, o el edificio es muy pesado, se usan <strong>cimentaciones profundas</strong> — pilotes que se hincan hasta encontrar una capa de suelo capaz de soportar el peso.</p><div class=\"example\">🧪 Es como pisar nieve: con zapatos normales te hundes, pero con raquetas de nieve (que reparten tu peso en más área) flotas sobre la superficie. Una zapata ancha hace lo mismo con el suelo.</div><div class=\"warn\">⚠️ La Torre de Pisa se inclina precisamente porque su cimentación es desigual sobre un suelo blando de un lado — un recordatorio célebre de que ignorar el estudio del suelo tiene consecuencias visibles durante siglos.</div><h2>Por qué nadie lo ve, pero todo depende de eso</h2><div class=\"tip\">💡 Una cimentación bien hecha es invisible — literalmente enterrada — pero es la parte del edificio que decide si todo lo demás se mantiene en pie.</div>","exercises":[{"id":"civ-04-1","type":"challenge","prompt":"Investiga (o recuerda) un caso real de un edificio inclinado o hundido por problemas de cimentación, además de la Torre de Pisa. Descríbelo brevemente y compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuándo se necesita una cimentación profunda (pilotes) en vez de una superficial?","options":["Cuando el edificio es de un solo piso","Cuando el suelo firme está muy profundo o el edificio es muy pesado","Siempre, sin excepción","Solo en zonas sin sismos"],"correctIndex":1},"comments":[]},{"id":"civ-05","order":5,"type":"text","title":"Infraestructura: puentes, carreteras y agua","description":"Cómo la ingeniería civil conecta ciudades enteras, no solo edificios individuales.","content":"<h2>Puentes: tres familias principales</h2><ul><li><strong>Puente de vigas:</strong> el más simple, apoyado directamente en pilares — ideal para claros cortos.</li><li><strong>Puente en arco:</strong> transfiere el peso hacia los lados por compresión — usado desde la Roma antigua.</li><li><strong>Puente colgante/atirantado:</strong> usa cables en tensión sostenidos por torres — permite los claros más largos del mundo (como el Golden Gate).</li></ul><h2>Carreteras: más capas de lo que parece</h2><p>Una carretera no es solo asfalto — típicamente tiene varias capas: una base de suelo compactado, una sub-base de grava, una base de material más fino, y finalmente el asfalto o concreto visible. Cada capa reparte el peso del tráfico hacia el suelo de forma gradual.</p><h2>Agua: la infraestructura invisible</h2><p>Bajo cada ciudad corre una red doble: tuberías que <strong>traen</strong> agua potable, y un sistema de drenaje separado que <strong>se lleva</strong> el agua de lluvia y las aguas residuales. Cuando estos sistemas fallan o son insuficientes, el resultado son inundaciones o contaminación.</p><div class=\"tip\">💡 La infraestructura civil rara vez se nota cuando funciona bien — solo se hace visible cuando falla (un bache, una inundación, un puente cerrado). Es, en ese sentido, un trabajo diseñado para ser invisible.</div>","exercises":[{"id":"civ-05-1","type":"challenge","prompt":"Elige un tipo de puente (vigas, arco o colgante) y explica por qué crees que se elegiría ese tipo para cruzar un río ancho vs. uno angosto. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué tipo de puente permite los claros (distancias) más largos del mundo?","options":["Puente de vigas","Puente en arco","Puente colgante/atirantado","Todos permiten la misma distancia"],"correctIndex":2},"comments":[]}]'::jsonb),
  ('course-ing-mecanica', 'Fundamentos de Ingeniería Mecánica', 'Cómo se diseñan las máquinas: fuerzas, movimiento, energía y los mecanismos que convierten una cosa en otra.', 'Eres el Mago, tutor de Fundamentos de Ingeniería Mecánica en Oliver Academy. Explica las leyes de Newton y la termodinámica con ejemplos de máquinas cotidianas (bicicletas, motores de coche, refrigeradores) antes de las fórmulas. Sé paciente con quien no tenga base de física previa.', '⚙️', '#64748b', 'Ingeniería', 'Mecánica', null, false, '[{"id":"mec-01","order":1,"type":"text","title":"¿Qué hace un ingeniero mecánico?","description":"La ingeniería del movimiento, la energía y las máquinas.","content":"<h2>La ingeniería más amplia de todas</h2><p>Si la ingeniería civil construye lo que no se mueve, la <strong>ingeniería mecánica</strong> diseña lo que sí se mueve — o lo que convierte un tipo de energía en otro. Es una de las ramas más amplias: motores, robots, aire acondicionado, prótesis, turbinas de avión, la suspensión de un coche.</p><h2>Tres pilares de la disciplina</h2><ul><li><strong>Mecánica:</strong> fuerzas, movimiento y estructuras que se mueven.</li><li><strong>Termodinámica:</strong> cómo fluye y se transforma la energía (calor, trabajo).</li><li><strong>Diseño de máquinas:</strong> cómo convertir esos principios en un objeto que funcione, se fabrique y dure.</li></ul><div class=\"tip\">💡 Un ingeniero mecánico piensa en términos de \"energía que entra, energía que sale, y qué se pierde en el camino\" — casi ninguna máquina es 100% eficiente, y entender esa pérdida es parte central del trabajo.</div>","exercises":[{"id":"mec-01-1","type":"challenge","prompt":"Elige una máquina que uses todos los días (licuadora, bicicleta, ventilador) e identifica: ¿qué tipo de energía entra y qué tipo de movimiento o resultado produce? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuáles son los tres pilares centrales de la ingeniería mecánica según este módulo?","options":["Química, biología y física","Mecánica, termodinámica y diseño de máquinas","Programación, redes y bases de datos","Arquitectura, urbanismo y paisajismo"],"correctIndex":1},"comments":[]},{"id":"mec-02","order":2,"type":"text","title":"Las leyes de Newton aplicadas al diseño","description":"Los tres principios que explican por qué las cosas se mueven (o no).","content":"<h2>Primera ley: inercia</h2><p>Un objeto en reposo sigue en reposo, y uno en movimiento sigue moviéndose en línea recta, a menos que una fuerza actúe sobre él. Por eso un coche que frena de golpe hace que los pasajeros sigan \"de frente\" — no es magia, es inercia, y por eso existe el cinturón de seguridad.</p><h2>Segunda ley: F = m·a</h2><p>La fuerza necesaria para acelerar algo depende de su masa: a mayor masa, más fuerza se necesita para el mismo cambio de velocidad. Es la ecuación central del diseño mecánico — de ahí sale casi todo el cálculo de motores, frenos y estructuras móviles.</p><div class=\"example\">🧪 Por eso un camión cargado necesita frenos mucho más potentes que una bicicleta para detenerse en la misma distancia — su masa es enormemente mayor.</div><h2>Tercera ley: acción y reacción</h2><p>Toda fuerza tiene una reacción igual y opuesta. Un cohete se impulsa empujando gas hacia atrás con tanta fuerza que el gas lo empuja a él hacia adelante — no \"empuja contra el aire\", funciona igual en el vacío del espacio.</p><div class=\"tip\">💡 Estas tres leyes, formuladas por Newton en 1687, siguen siendo la base del diseño mecánico cotidiano — no hace falta física relativista para diseñar un motor de coche.</div>","exercises":[{"id":"mec-02-1","type":"challenge","prompt":"Explica, usando la tercera ley de Newton, por qué un cohete puede impulsarse incluso en el vacío del espacio (donde no hay aire contra el cual \"empujar\"). Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"Según la segunda ley de Newton (F = m·a), ¿qué pasa si aumenta la masa de un objeto y quieres la misma aceleración?","options":["Se necesita menos fuerza","Se necesita más fuerza","La masa no afecta la fuerza necesaria","Solo importa la velocidad, no la masa"],"correctIndex":1},"comments":[]},{"id":"mec-03","order":3,"type":"text","title":"Termodinámica básica: motores y energía","description":"Cómo se convierte calor en movimiento — y por qué nunca al 100%.","content":"<h2>Energía: no se crea ni se destruye</h2><p>La <strong>primera ley de la termodinámica</strong> dice que la energía no desaparece, solo se transforma de un tipo a otro (química → calor → movimiento, por ejemplo). Un motor de combustión convierte la energía química de la gasolina en calor, y ese calor en movimiento.</p><h2>La segunda ley: nunca 100% eficiente</h2><p>Ninguna máquina convierte toda la energía que recibe en trabajo útil — siempre se pierde algo, casi siempre como calor disperso (fricción, escape). La <strong>eficiencia</strong> de un motor es el porcentaje de energía que sí se aprovecha.</p><div class=\"example\">🧪 Un motor de combustión típico de coche solo aprovecha entre 20% y 40% de la energía de la gasolina en movimiento real — el resto se pierde como calor. Es una de las razones por las que los motores eléctricos (más eficientes, +85%) han ganado terreno.</div><h2>Ciclos termodinámicos</h2><p>Motores, refrigeradores y aires acondicionados funcionan repitiendo un <strong>ciclo</strong> de pasos (comprimir, calentar, expandir, enfriar) una y otra vez — el mismo principio básico, aplicado en direcciones distintas: un motor usa calor para producir movimiento, un refrigerador usa movimiento (el compresor) para quitar calor de un espacio.</p><div class=\"tip\">💡 Un refrigerador no \"produce frío\" — mueve el calor de adentro hacia afuera. Por eso la parte trasera de un refrigerador siempre está tibia: ahí es donde bota el calor que sacó de la comida.</div>","exercises":[{"id":"mec-03-1","type":"challenge","prompt":"¿Por qué la parte trasera de un refrigerador está siempre tibia? Explica usando la idea de \"mover calor\" en vez de \"producir frío\". Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"Según la segunda ley de la termodinámica, ¿qué porcentaje de energía puede aprovechar una máquina real?","options":["Siempre el 100%","Nunca el 100% — siempre se pierde algo, típicamente como calor","Depende únicamente del precio de la máquina","Solo las máquinas eléctricas pierden energía"],"correctIndex":1},"comments":[]},{"id":"mec-04","order":4,"type":"text","title":"Materiales y resistencia mecánica","description":"Por qué un mismo diseño falla con un material y funciona con otro.","content":"<h2>Esfuerzo y deformación</h2><p>Cuando aplicas fuerza a un material, este se deforma. Si al quitar la fuerza vuelve a su forma original, la deformación fue <strong>elástica</strong> (como un resorte). Si se queda deformado permanentemente, fue <strong>plástica</strong>. Si se rompe, alcanzó su <strong>límite de resistencia</strong>.</p><div class=\"example\">🧪 Doblar un clip de metal un poco y que regrese: elástico. Doblarlo hasta que quede torcido: plástico. Doblarlo hasta que se parta: fractura.</div><h2>Fatiga: el enemigo silencioso</h2><p>Un material puede romperse con una fuerza mucho menor a su límite si esa fuerza se repite miles o millones de veces — esto se llama <strong>fatiga</strong>, y es la causa de muchas fallas mecánicas inesperadas (una pieza de avión, un eje que gira constantemente).</p><div class=\"warn\">⚠️ La fatiga es traicionera precisamente porque la pieza parece estar bien hasta el momento exacto en que falla — por eso el mantenimiento preventivo (reemplazar piezas ANTES de que fallen, según su vida útil calculada) es tan central en ingeniería mecánica.</div><h2>Elegir el material correcto</h2><p>Un ingeniero mecánico no busca \"el material más fuerte\" en abstracto — busca el balance correcto entre resistencia, peso, costo, resistencia a la corrosión y facilidad de fabricación para ESE diseño específico.</p>","exercises":[{"id":"mec-04-1","type":"challenge","prompt":"Piensa en un objeto metálico que se haya roto por uso repetido (una liga, un clip, una llave) más que por un solo golpe fuerte. ¿Reconoces ahí el concepto de fatiga? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué es la \"fatiga\" en un material?","options":["Que se oxide con el tiempo","Que se rompa con fuerza repetida, aunque cada fuerza sea menor a su límite","Que pese demasiado","Que sea difícil de fabricar"],"correctIndex":1},"comments":[]},{"id":"mec-05","order":5,"type":"text","title":"Máquinas simples y mecanismos","description":"Los seis bloques básicos con los que se construye cualquier máquina compleja.","content":"<h2>Las seis máquinas simples clásicas</h2><ul><li><strong>Palanca:</strong> multiplica fuerza a cambio de distancia (un desarmador haciendo palanca).</li><li><strong>Polea:</strong> cambia la dirección de una fuerza, o la multiplica con varias poleas juntas.</li><li><strong>Plano inclinado:</strong> una rampa reduce la fuerza necesaria a cambio de más distancia recorrida.</li><li><strong>Cuña:</strong> un plano inclinado que se mueve, usado para cortar o separar.</li><li><strong>Tornillo:</strong> un plano inclinado enrollado — convierte giro en movimiento lineal.</li><li><strong>Rueda y eje:</strong> multiplica la fuerza de giro (una manija de puerta).</li></ul><div class=\"tip\">💡 Ninguna de estas seis \"crea\" energía de la nada — todas cambian la relación entre fuerza y distancia (más fuerza a cambio de menos distancia, o viceversa), respetando siempre la conservación de energía.</div><h2>Mecanismos: máquinas simples combinadas</h2><p>Un engranaje es una rueda con dientes; combinar varios engranajes de distinto tamaño permite multiplicar fuerza o velocidad de giro con precisión — la base de relojes mecánicos, cajas de velocidades de coches, y la transmisión de una bicicleta.</p><div class=\"example\">🧪 En una bicicleta, cambiar a un piñón trasero más grande facilita pedalear cuesta arriba (más fuerza, menos velocidad) — es exactamente el mismo principio de las máquinas simples, aplicado con engranajes.</div>","exercises":[{"id":"mec-05-1","type":"challenge","prompt":"Identifica al menos 3 máquinas simples (palanca, polea, plano inclinado, cuña, tornillo, rueda y eje) presentes en objetos de tu casa. Descríbelas y compártelas con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué tienen en común las seis máquinas simples clásicas?","options":["Todas usan electricidad","Todas cambian la relación entre fuerza y distancia, sin crear energía de la nada","Todas fueron inventadas en el siglo XX","Todas requieren motores"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-ing-electrica', 'Fundamentos de Ingeniería Eléctrica y Electrónica', 'Voltaje, corriente, circuitos y los componentes que hacen posible desde un foco hasta un microchip — explicado desde cero.', 'Eres el Mago, tutor de Fundamentos de Ingeniería Eléctrica y Electrónica en Oliver Academy. Usa la analogía del agua (voltaje=presión, corriente=flujo, resistencia=una tubería angosta) para explicar circuitos antes de fórmulas. Sé paciente con quien nunca haya tocado electrónica.', '🔌', '#eab308', 'Ingeniería', 'Eléctrica y Electrónica', null, false, '[{"id":"ele-01","order":1,"type":"text","title":"Electricidad básica: voltaje, corriente y resistencia","description":"Los tres conceptos que explican todo circuito eléctrico, usando la analogía del agua.","content":"<h2>La analogía del agua</h2><p>Imagina un circuito eléctrico como una tubería de agua:</p><ul><li><strong>Voltaje (V):</strong> la presión del agua — cuánta \"fuerza\" empuja el flujo. Se mide en <strong>volts</strong>.</li><li><strong>Corriente (I):</strong> qué tanta agua fluye realmente por la tubería. Se mide en <strong>amperes</strong>.</li><li><strong>Resistencia (R):</strong> qué tan angosta está la tubería — entre más angosta, más le cuesta al agua pasar. Se mide en <strong>ohms</strong>.</li></ul><div class=\"tip\">💡 Esta analogía no es perfecta pero es suficientemente buena para razonar sobre el 90% de los circuitos básicos: más voltaje empuja más corriente; más resistencia frena esa corriente.</div><h2>Corriente: el flujo de electrones</h2><p>Físicamente, la corriente eléctrica es el movimiento de electrones a través de un material conductor (normalmente metal). Un <strong>circuito</strong> es simplemente un camino cerrado por el que esos electrones pueden fluir, desde una fuente de energía (batería) hasta de vuelta a ella.</p>","exercises":[{"id":"ele-01-1","type":"challenge","prompt":"Usando la analogía del agua, explica con tus palabras por qué una tubería más angosta (más resistencia) permite pasar menos agua (corriente) con la misma presión (voltaje). Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"En la analogía del agua, ¿qué representa la resistencia?","options":["La presión del agua","Qué tan angosta está la tubería","La cantidad total de agua","El color del agua"],"correctIndex":1},"comments":[]},{"id":"ele-02","order":2,"type":"text","title":"Ley de Ohm y circuitos simples","description":"La ecuación más usada en electrónica: V = I × R.","content":"<h2>La ecuación central</h2><p>La <strong>Ley de Ohm</strong> relaciona los tres conceptos del módulo anterior: <code>V = I × R</code> (Voltaje = Corriente × Resistencia). Con dos de estos valores, siempre puedes calcular el tercero.</p><div class=\"example\">🧪 Si una batería de 9V se conecta a una resistencia de 3 ohms, la corriente será: I = V/R = 9/3 = 3 amperes.</div><h2>Circuitos en serie vs. en paralelo</h2><p>En un circuito <strong>en serie</strong>, los componentes están conectados uno tras otro en un solo camino — si uno falla, todo el circuito se interrumpe (como luces navideñas antiguas). En un circuito <strong>en paralelo</strong>, cada componente tiene su propio camino hacia la fuente — si uno falla, los demás siguen funcionando (como el cableado de una casa).</p><div class=\"warn\">⚠️ Por eso el cableado doméstico siempre es en paralelo: si se funde un foco, no quieres que se apague toda la casa.</div><h2>¿Por qué importa la Ley de Ohm?</h2><div class=\"tip\">💡 Casi cualquier diseño de circuito, desde el más simple hasta el chip más complejo, se reduce en algún punto a aplicar esta misma ecuación para decidir qué componente usar.</div>","exercises":[{"id":"ele-02-1","type":"challenge","prompt":"Usando V = I × R, calcula la corriente si una batería de 12V se conecta a una resistencia de 4 ohms. Muestra tu cálculo y compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué pasa en un circuito en serie si uno de los componentes falla?","options":["Los demás siguen funcionando normalmente","Todo el circuito se interrumpe","El voltaje se duplica","No pasa nada"],"correctIndex":1},"comments":[]},{"id":"ele-03","order":3,"type":"text","title":"Corriente directa vs. alterna","description":"Por qué las baterías y los enchufes de pared usan tipos distintos de corriente.","content":"<h2>Corriente directa (DC)</h2><p>En la <strong>corriente directa</strong>, los electrones fluyen siempre en la misma dirección — es lo que producen las baterías, y lo que usan casi todos los circuitos electrónicos internos (chips, procesadores).</p><h2>Corriente alterna (AC)</h2><p>En la <strong>corriente alterna</strong>, la dirección del flujo se invierte muchas veces por segundo (60 veces por segundo en México y gran parte de América). Es la que sale de los enchufes de pared, porque se puede transmitir a larga distancia con mucha menos pérdida de energía que la DC.</p><div class=\"example\">🧪 Por eso casi todo aparato electrónico que enchufas a la pared (laptop, cargador de celular) tiene una \"caja\" o adaptador — su trabajo es convertir la AC de la pared en la DC que el aparato realmente necesita por dentro.</div><h2>La guerra de las corrientes</h2><div class=\"tip\">💡 A finales del siglo XIX, Thomas Edison (DC) y Nikola Tesla/George Westinghouse (AC) compitieron públicamente por cuál sistema dominaría la electrificación mundial. Ganó la AC, precisamente por su ventaja para transmitirse a largas distancias — una decisión de ingeniería que todavía define cómo llega la electricidad a tu casa hoy.</div>","exercises":[{"id":"ele-03-1","type":"challenge","prompt":"¿Por qué crees que un cargador de laptop o celular necesita convertir la corriente de la pared antes de llegar al aparato? Explica con tus palabras y compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Por qué se eligió la corriente alterna (AC) para la red eléctrica de larga distancia?","options":["Porque es más segura para tocar","Porque se transmite con mucha menos pérdida de energía a larga distancia","Porque las baterías la producen naturalmente","Porque fue la primera en inventarse"],"correctIndex":1},"comments":[]},{"id":"ele-04","order":4,"type":"text","title":"Componentes electrónicos: diodos, transistores y chips","description":"Las piezas que hacen posible controlar la electricidad con precisión.","content":"<h2>El diodo: una calle de un solo sentido</h2><p>Un <strong>diodo</strong> deja pasar la corriente en una sola dirección y la bloquea en la otra — es la versión electrónica de una válvula de un solo sentido. Se usa, por ejemplo, para convertir AC en DC (rectificación).</p><h2>El transistor: el interruptor que cambió el mundo</h2><p>Un <strong>transistor</strong> es un interruptor electrónico sin partes móviles: una pequeña señal eléctrica controla si deja pasar (o amplifica) una corriente mucho mayor. Inventado en 1947, reemplazó a los tubos de vacío — más pequeño, más rápido, más confiable y muchísimo más barato de fabricar en masa.</p><div class=\"example\">🧪 Un chip de computadora moderno contiene miles de millones de transistores diminutos, cada uno actuando como un interruptor de encendido/apagado — esos \"encendido/apagado\" son literalmente los unos y ceros del código binario que corre por dentro de cualquier computadora.</div><div class=\"tip\">💡 La miniaturización de los transistores — cada vez más pequeños y más numerosos en el mismo chip — es la base física detrás de por qué las computadoras se han vuelto exponencialmente más potentes cada década (la llamada \"Ley de Moore\").</div>","exercises":[{"id":"ele-04-1","type":"challenge","prompt":"Investiga (o recuerda) qué es la \"Ley de Moore\" y explica con tus palabras qué relación tiene con los transistores. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué hace un transistor, en esencia?","options":["Genera electricidad de la nada","Actúa como un interruptor electrónico sin partes móviles","Almacena datos permanentemente","Convierte luz en sonido"],"correctIndex":1},"comments":[]},{"id":"ele-05","order":5,"type":"text","title":"De la electrónica analógica a la digital","description":"Por qué casi todo lo nuevo se diseña en digital, aunque el mundo real sea analógico.","content":"<h2>Señales analógicas: continuas, como el mundo real</h2><p>Una señal <strong>analógica</strong> puede tomar cualquier valor dentro de un rango continuo — el volumen real de un sonido, la temperatura real de un cuarto. Los primeros circuitos electrónicos (radios, televisores antiguos) eran completamente analógicos.</p><h2>Señales digitales: solo dos estados</h2><p>Una señal <strong>digital</strong> solo reconoce dos estados — encendido/apagado, 1/0 — representados por rangos de voltaje (por ejemplo, \"alto\" = cerca de 5V, \"bajo\" = cerca de 0V). Es mucho más resistente al ruido: una pequeña interferencia eléctrica puede arruinar una señal analógica sutil, pero rara vez confunde un \"claramente alto\" con un \"claramente bajo\".</p><div class=\"example\">🧪 Por eso una llamada telefónica antigua (analógica) se degradaba con estática y ruido de línea, mientras que una llamada por internet (digital) o se escucha perfecta o se corta — no hay un \"punto medio ruidoso\" en la información digital.</div><h2>El puente entre ambos mundos</h2><p>El mundo físico (sonido, luz, temperatura) es analógico por naturaleza. Un <strong>convertidor analógico-digital (ADC)</strong> traduce esas señales continuas a números digitales que una computadora puede procesar — el micrófono de tu celular hace exactamente esto, decenas de miles de veces por segundo.</p><div class=\"tip\">💡 Esta distinción — analógico vs. digital — es la frontera exacta donde la ingeniería eléctrica se conecta con la programación: los \"1\" y \"0\" de cualquier lenguaje de programación son, en el fondo, voltajes altos y bajos reales dentro de un chip.</div>","exercises":[{"id":"ele-05-1","type":"challenge","prompt":"Explica con tus palabras por qué una señal digital es más resistente al ruido/interferencia que una señal analógica. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué hace un convertidor analógico-digital (ADC)?","options":["Convierte corriente alterna en directa","Traduce señales continuas del mundo real a números digitales","Aumenta el voltaje de una batería","Elimina la necesidad de transistores"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-ing-industrial', 'Fundamentos de Ingeniería Industrial', 'Cómo se optimizan procesos, calidad y personas: de la línea de producción a la cadena de suministro global.', 'Eres el Mago, tutor de Fundamentos de Ingeniería Industrial en Oliver Academy. Explica procesos, calidad y logística con ejemplos de la vida cotidiana (una cocina, una fila de un banco, un pedido en línea) antes de la terminología formal. Sé práctico y concreto.', '🏭', '#0ea5e9', 'Ingeniería', 'Industrial', null, false, '[{"id":"ind-01","order":1,"type":"text","title":"¿Qué hace un ingeniero industrial?","description":"La ingeniería de \"hacer las cosas mejor\", no de un producto en particular.","content":"<h2>No diseña el producto, diseña el proceso</h2><p>Mientras otras ingenierías diseñan UN objeto (un puente, un motor, un circuito), la <strong>ingeniería industrial</strong> diseña y optimiza <strong>procesos</strong>: cómo fabricar algo más rápido, con menos desperdicio, con mejor calidad y con las personas trabajando de forma más segura y eficiente.</p><h2>Un campo aplicable a casi todo</h2><p>Un ingeniero industrial puede trabajar en una fábrica, un hospital (optimizando el flujo de pacientes), un banco (optimizando filas), o una empresa de logística (optimizando rutas de entrega) — el principio es el mismo: analizar un proceso, medirlo, y mejorarlo.</p><div class=\"tip\">💡 Si la pregunta es \"¿cómo hacemos esto más rápido, más barato o con menos errores, sin sacrificar calidad?\" — esa es, en esencia, la pregunta central de la ingeniería industrial.</div>","exercises":[{"id":"ind-01-1","type":"challenge","prompt":"Piensa en un proceso cotidiano que te parezca ineficiente (una fila, un trámite, una forma de organizar algo). ¿Qué cambiarías para mejorarlo? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿En qué se diferencia principalmente la ingeniería industrial de otras ramas de la ingeniería?","options":["Diseña un producto físico específico","Diseña y optimiza procesos, no un objeto en particular","Solo trabaja en fábricas","No requiere matemáticas"],"correctIndex":1},"comments":[]},{"id":"ind-02","order":2,"type":"text","title":"Procesos y líneas de producción","description":"Cómo Henry Ford cambió para siempre la forma de fabricar cosas.","content":"<h2>Antes de la línea de ensamblaje</h2><p>A principios del siglo XX, fabricar un coche era un proceso artesanal: un equipo de trabajadores construía un vehículo completo, de principio a fin, uno a la vez. Era lento y costoso.</p><h2>La línea de ensamblaje de Ford (1913)</h2><p>Henry Ford dividió la fabricación de un coche en <strong>tareas pequeñas y repetibles</strong>, cada una realizada por un trabajador especializado en una estación fija, mientras el vehículo se movía de estación en estación en una banda transportadora. El tiempo de fabricación de un Ford Model T cayó de más de 12 horas a poco más de 90 minutos.</p><div class=\"example\">🧪 Es el mismo principio detrás de una línea de comida rápida moderna: una persona pone el pan, otra la carne, otra los vegetales — cada quien domina UNA tarea y la repite rápido, en vez de que una sola persona arme cada orden completa desde cero.</div><h2>El costo de esta eficiencia</h2><div class=\"warn\">⚠️ La especialización extrema de tareas también puede volver el trabajo monótono y desconectar al trabajador del producto final — un tema que la ingeniería industrial moderna trata de balancear junto con la ergonomía y la motivación humana (ver el último módulo de este curso).</div>","exercises":[{"id":"ind-02-1","type":"challenge","prompt":"Describe un proceso que conozcas (una cocina, una fábrica, un almacén) donde identifiques \"estaciones\" especializadas, como en una línea de ensamblaje. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué logró la línea de ensamblaje de Henry Ford?","options":["Aumentó el costo de producción","Redujo drásticamente el tiempo de fabricación al dividir el trabajo en tareas repetibles","Eliminó la necesidad de trabajadores","Solo funcionó para fabricar comida"],"correctIndex":1},"comments":[]},{"id":"ind-03","order":3,"type":"text","title":"Calidad: de la inspección a Six Sigma","description":"Cómo pasó la industria de \"revisar al final\" a \"prevenir desde el inicio\".","content":"<h2>El enfoque viejo: inspeccionar al final</h2><p>Durante décadas, \"control de calidad\" significaba fabricar el producto y luego revisar cuáles unidades salieron defectuosas para descartarlas — caro, lento, y no evita que el defecto ocurra la próxima vez.</p><h2>El enfoque moderno: prevenir el defecto</h2><p>La filosofía moderna de calidad busca entender la <strong>causa raíz</strong> de un defecto y corregir el proceso mismo, no solo descartar el producto malo. <strong>Six Sigma</strong> es una de las metodologías más conocidas: usa estadística para medir cuánta variación tiene un proceso, con la meta de reducir los defectos a menos de 3.4 por millón de oportunidades.</p><div class=\"example\">🧪 Si una fábrica de tornillos descubre que 1 de cada 100 sale con la rosca defectuosa, el enfoque viejo sería \"revisar los 100 y tirar el malo\". El enfoque Six Sigma pregunta: ¿por qué está saliendo defectuoso? ¿Vibra la máquina? ¿Se desgastó una herramienta? — y corrige esa causa.</div><div class=\"tip\">💡 La idea central de la calidad moderna en una frase: es mucho más barato prevenir un defecto que corregirlo después de que ya salió de la fábrica (o peor, después de que llegó al cliente).</div>","exercises":[{"id":"ind-03-1","type":"challenge","prompt":"Piensa en un producto defectuoso que hayas recibido alguna vez. ¿Crees que el problema fue algo que se podía prevenir desde el proceso, o fue mala suerte aislada? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es la diferencia central entre el enfoque viejo y el moderno de control de calidad?","options":["El enfoque moderno inspecciona más productos al final","El enfoque moderno busca corregir la causa raíz del defecto, no solo descartar productos malos","No hay diferencia real","El enfoque viejo es más barato"],"correctIndex":1},"comments":[]},{"id":"ind-04","order":4,"type":"text","title":"Logística y cadena de suministro","description":"Todo lo que pasa entre \"se fabrica\" y \"llega a tu puerta\".","content":"<h2>¿Qué es una cadena de suministro?</h2><p>La <strong>cadena de suministro</strong> es toda la red de pasos entre la materia prima y el producto final en manos del consumidor: proveedores, fábricas, almacenes, transporte, tiendas (o entrega directa). Un ingeniero industrial diseña y optimiza esta red completa, no solo un eslabón.</p><h2>Inventario: el balance difícil</h2><p>Tener demasiado inventario cuesta dinero (almacenamiento, productos que se vuelven obsoletos). Tener muy poco inventario significa quedarse sin producto cuando hay demanda — perder ventas. Encontrar el balance correcto es uno de los problemas centrales de la logística.</p><div class=\"example\">🧪 El sistema \"justo a tiempo\" (just-in-time), popularizado por Toyota, busca recibir materiales exactamente cuando se necesitan para producir, minimizando el inventario almacenado — funciona increíble cuando todo sale según lo planeado, pero es frágil ante interrupciones inesperadas (como se vio durante la pandemia de 2020, cuando cadenas enteras se quedaron sin insumos).</div><div class=\"tip\">💡 La próxima vez que un pedido en línea te llegue en 24 horas, piensa en cuántos eslabones de esta cadena tuvieron que coordinarse — casi ninguno de ellos lo notas, hasta que algo falla.</div>","exercises":[{"id":"ind-04-1","type":"challenge","prompt":"Explica con tus palabras la ventaja y el riesgo del sistema \"justo a tiempo\" (just-in-time) para el inventario. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué busca minimizar el sistema \"justo a tiempo\" (just-in-time)?","options":["El número de proveedores","El inventario almacenado, recibiendo materiales justo cuando se necesitan","El número de trabajadores","El tiempo de entrega al cliente final"],"correctIndex":1},"comments":[]},{"id":"ind-05","order":5,"type":"text","title":"Ergonomía y factor humano","description":"Por qué diseñar un proceso eficiente también significa diseñarlo para personas reales.","content":"<h2>El trabajador no es una máquina más</h2><p>Un proceso puede ser matemáticamente \"óptimo\" en papel y aun así fallar si ignora la fatiga, el aburrimiento o el riesgo de lesión de las personas que lo ejecutan. La <strong>ergonomía</strong> estudia cómo diseñar herramientas, espacios de trabajo y tareas que se ajusten al cuerpo y la mente humana, no al revés.</p><h2>Ejemplos concretos</h2><ul><li>La altura de una mesa de trabajo, ajustada para evitar dolor de espalda repetido.</li><li>Rotar tareas entre trabajadores para evitar lesiones por movimiento repetitivo.</li><li>Diseñar controles y pantallas intuitivos que reduzcan errores humanos, en vez de culpar al operador cuando algo sale mal.</li></ul><div class=\"warn\">⚠️ Un error clásico de diseño es asumir que \"si algo sale mal, fue error humano\" — la ergonomía moderna asume lo contrario: si muchas personas distintas cometen el mismo error en el mismo punto, probablemente el diseño del proceso es el problema, no la gente.</div><h2>Cierre del curso</h2><div class=\"tip\">💡 Con esto cierras un recorrido completo por la ingeniería industrial: procesos (Ford), calidad (Six Sigma), logística (cadena de suministro) y, finalmente, el factor humano que sostiene todo lo anterior — ninguna optimización vale si ignora a las personas que la ejecutan día a día.</div>","exercises":[{"id":"ind-05-1","type":"challenge","prompt":"Piensa en un objeto o espacio de trabajo mal diseñado que te haya causado incomodidad o un error (una silla, un formulario confuso, un botón mal ubicado). Rediséñalo con tus palabras y compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"Según la ergonomía moderna, si muchas personas distintas cometen el mismo error en el mismo punto de un proceso, ¿qué es lo más probable?","options":["Que todas esas personas sean descuidadas","Que el diseño del proceso tenga un problema, no la gente","Que se necesite más supervisión, nada más","Que sea pura coincidencia"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-ing-software', 'Fundamentos de Ingeniería de Software', 'La diferencia entre "programar" y construir software real: ciclo de vida, metodologías, control de versiones y calidad.', 'Eres el Mago, tutor de Fundamentos de Ingeniería de Software en Oliver Academy. Conecta cada concepto con cómo se construye realmente esta plataforma (control de versiones con Git, testing, metodología ágil informal) cuando sea posible. Sé práctico, no solo teórico.', '🖥️', '#22c55e', 'Ingeniería', 'Software y Sistemas', null, false, '[{"id":"sw-01","order":1,"type":"text","title":"¿Qué es la ingeniería de software (y en qué se diferencia de \"programar\")?","description":"Escribir código es solo una parte de construir software real.","content":"<h2>Programar vs. construir software</h2><p><strong>Programar</strong> es escribir instrucciones que una computadora ejecute. La <strong>ingeniería de software</strong> es la disciplina más amplia de construir, mantener y evolucionar sistemas de software completos — lo cual incluye programar, pero también planear, documentar, probar, colaborar en equipo y mantener el sistema funcionando durante años, no solo el día en que se escribió.</p><h2>Por qué la distinción importa</h2><p>Un programa de 50 líneas que escribes para ti mismo, una sola vez, casi no necesita ingeniería. Un sistema que va a usar miles de personas, que va a recibir cambios de decenas de programadores distintos durante años, sí la necesita — de lo contrario se vuelve imposible de mantener.</p><div class=\"tip\">💡 El curso de Principios SOLID de esta misma academia y este curso están profundamente conectados: SOLID es una de las herramientas concretas que usa la ingeniería de software para que un sistema grande siga siendo manejable con el tiempo.</div>","exercises":[{"id":"sw-01-1","type":"challenge","prompt":"¿Alguna vez escribiste algo pequeño (un script, una hoja de cálculo con fórmulas) que con el tiempo creció tanto que se volvió difícil de entender o mantener? Descríbelo y compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es la diferencia central entre \"programar\" y \"ingeniería de software\" según este módulo?","options":["No hay ninguna diferencia real","Programar es solo escribir código; la ingeniería de software incluye planear, probar, documentar y mantener el sistema en el tiempo","La ingeniería de software no incluye programar","Programar siempre requiere un equipo grande"],"correctIndex":1},"comments":[]},{"id":"sw-02","order":2,"type":"text","title":"El ciclo de vida del software","description":"De la idea al mantenimiento: las etapas por las que pasa cualquier sistema real.","content":"<h2>Las etapas clásicas</h2><ol><li><strong>Requisitos:</strong> entender qué problema hay que resolver y para quién.</li><li><strong>Diseño:</strong> planear la arquitectura de la solución antes de escribir código.</li><li><strong>Implementación:</strong> escribir el código real.</li><li><strong>Pruebas (testing):</strong> verificar que funciona como se esperaba.</li><li><strong>Despliegue:</strong> poner el sistema en manos de usuarios reales.</li><li><strong>Mantenimiento:</strong> corregir errores, agregar funciones, adaptarse a cambios — la etapa más larga de todas.</li></ol><div class=\"warn\">⚠️ Un error común de principiante es saltarse directo a \"implementación\" sin pasar por requisitos y diseño — casi siempre resulta en tener que reescribir partes grandes del sistema más adelante, porque se entendió mal el problema desde el inicio.</div><h2>El mantenimiento es la etapa más larga (y más subestimada)</h2><div class=\"tip\">💡 La mayoría del \"tiempo de vida\" de un sistema de software real no se gasta escribiéndolo por primera vez — se gasta manteniéndolo: corrigiendo errores que aparecen con el uso real, y agregando funciones que nadie pidió al inicio pero que se vuelven necesarias después.</div>","exercises":[{"id":"sw-02-1","type":"challenge","prompt":"Piensa en una app o sitio web que uses seguido. ¿Qué funciones crees que se agregaron DESPUÉS del lanzamiento original, durante su \"mantenimiento\"? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es, típicamente, la etapa más larga del ciclo de vida de un software?","options":["Requisitos","Implementación","Mantenimiento","Despliegue"],"correctIndex":2},"comments":[]},{"id":"sw-03","order":3,"type":"text","title":"Metodologías: cascada, ágil y Scrum","description":"Distintas formas de organizar el trabajo de construir software.","content":"<h2>Cascada: un plan completo, de principio a fin</h2><p>El modelo <strong>cascada</strong> completa cada etapa del ciclo de vida por completo antes de pasar a la siguiente — todos los requisitos se definen antes de diseñar, todo el diseño antes de programar. Funciona bien cuando los requisitos son estables y conocidos desde el inicio (por ejemplo, construir un puente), pero es rígido ante cambios.</p><h2>Ágil: entregar en pedazos pequeños, y ajustar sobre la marcha</h2><p>Las metodologías <strong>ágiles</strong> dividen el trabajo en ciclos cortos (semanas, no meses), entregando una versión funcional — aunque incompleta — al final de cada ciclo, e incorporando retroalimentación real antes de seguir. Esto asume, correctamente, que los requisitos casi siempre cambian una vez que los usuarios ven algo real.</p><h2>Scrum: la forma más popular de aplicar ágil</h2><p><strong>Scrum</strong> organiza el trabajo en ciclos llamados \"sprints\" (típicamente 1-4 semanas), con reuniones cortas diarias para sincronizar al equipo, y una revisión al final de cada sprint con lo que se logró.</p><div class=\"tip\">💡 Este mismo proyecto (Oliver Academy) se ha construido de forma iterativa e incremental — feature por feature, con retroalimentación constante — más parecido al espíritu ágil que a un plan de cascada fijado desde el día uno.</div>","exercises":[{"id":"sw-03-1","type":"challenge","prompt":"¿Preferirías planear un proyecto completo antes de empezar (cascada), o construir un poco, mostrarlo, y ajustar sobre la marcha (ágil)? Justifica tu respuesta y compártela con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué asume correctamente el enfoque ágil, a diferencia de cascada?","options":["Que los requisitos nunca cambian","Que los requisitos casi siempre cambian una vez que los usuarios ven algo real","Que no se necesita planear nada","Que solo sirve para proyectos pequeños"],"correctIndex":1},"comments":[]},{"id":"sw-04","order":4,"type":"text","title":"Control de versiones y trabajo en equipo (Git)","description":"Cómo cientos de personas pueden editar el mismo código sin destruirse el trabajo entre sí.","content":"<h2>El problema sin control de versiones</h2><p>Sin una herramienta de control de versiones, si dos personas editan el mismo archivo al mismo tiempo, una de las dos ediciones se perdería al guardar. Y si un cambio nuevo rompe algo, no habría forma fácil de volver exactamente a como estaba antes.</p><h2>Git: un historial completo y ramas paralelas</h2><p><strong>Git</strong> es la herramienta de control de versiones más usada en el mundo. Guarda un historial completo de cada cambio (quién, qué, cuándo), permite trabajar en <strong>ramas</strong> separadas sin afectar el código principal hasta que el cambio esté listo, y permite combinar (\"merge\") el trabajo de varias personas de forma controlada.</p><div class=\"example\">🧪 Cada commit en el historial de este mismo proyecto (visible en el tablón de anuncios del Dashboard) es exactamente esto: un punto guardado del código en un momento específico, con un mensaje que explica qué cambió.</div><h2>GitHub y la colaboración a gran escala</h2><p>GitHub (y servicios similares) alojan repositorios de Git en la nube, permitiendo que equipos — o comunidades enteras de código abierto — colaboren en el mismo proyecto desde cualquier lugar del mundo, revisando los cambios de otros antes de aceptarlos.</p><div class=\"tip\">💡 El control de versiones no es solo una herramienta técnica — es lo que hace posible que el software moderno se construya de forma colaborativa y distribuida, en vez de depender de una sola persona guardando archivos manualmente.</div>","exercises":[{"id":"sw-04-1","type":"challenge","prompt":"¿Alguna vez perdiste trabajo por sobreescribir un archivo sin querer, o por no tener una versión anterior guardada? Explica cómo el control de versiones habría evitado ese problema. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué problema resuelve principalmente una herramienta de control de versiones como Git?","options":["Hacer el código más rápido de ejecutar","Permitir que varias personas trabajen en el mismo código sin perder cambios, con un historial completo","Traducir código entre lenguajes","Eliminar la necesidad de pruebas"],"correctIndex":1},"comments":[]},{"id":"sw-05","order":5,"type":"text","title":"Testing y calidad de software","description":"Cómo saber que el software funciona, antes de que lo descubra un usuario real.","content":"<h2>¿Por qué probar antes de lanzar?</h2><p>Un error en software no descubierto a tiempo puede llegar a miles de usuarios reales, causar pérdida de datos, o en sistemas críticos (aviación, medicina) poner vidas en riesgo. El <strong>testing</strong> (pruebas) busca encontrar esos errores ANTES de que el usuario final los encuentre.</p><h2>Tipos de pruebas</h2><ul><li><strong>Pruebas unitarias:</strong> verifican que una pieza pequeña de código (una función) haga exactamente lo que debería, de forma aislada.</li><li><strong>Pruebas de integración:</strong> verifican que varias piezas trabajen bien juntas.</li><li><strong>Pruebas manuales/exploratorias:</strong> una persona real usa el sistema tratando de encontrar comportamientos inesperados.</li></ul><div class=\"example\">🧪 Antes de que cualquier función nueva de esta plataforma se dé por terminada, se hace una verificación de que el código compila sin errores (build) y, cuando aplica, se prueba manualmente en el navegador — el mismo espíritu del testing, aplicado de forma práctica.</div><h2>Cierre del curso</h2><div class=\"warn\">⚠️ Ningún proceso de testing garantiza CERO errores — la meta realista no es la perfección, sino reducir la probabilidad y el impacto de los errores que sí lleguen a producción.</div><div class=\"tip\">💡 Con esto completas un recorrido por los pilares de la ingeniería de software: entender que construir software es más que programar, seguir un ciclo de vida completo, elegir una metodología de trabajo, colaborar con control de versiones, y verificar la calidad antes de lanzar. Estos mismos pilares aplican sin importar qué lenguaje de programación uses después.</div>","exercises":[{"id":"sw-05-1","type":"challenge","prompt":"¿Alguna vez usaste una app que tenía un error (bug) obvio? ¿Qué tipo de prueba (unitaria, integración, manual) crees que habría podido detectarlo antes del lanzamiento? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es la meta realista del testing de software, según este módulo?","options":["Garantizar cero errores para siempre","Reducir la probabilidad y el impacto de los errores que lleguen a producción","Eliminar la necesidad de control de versiones","Hacer el código más corto"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-logica', 'Introducción a la Lógica', 'Lógica clásica, lógica matemática y sus falacias: cómo razonar de forma válida y detectar argumentos que solo PARECEN correctos.', 'Eres el Mago, tutor de Introducción a la Lógica en Oliver Academy. Usa ejemplos cotidianos y argumentos reales (noticias, debates, redes sociales) para ilustrar falacias y razonamiento válido, no solo símbolos abstractos. Sé paciente al introducir la notación de lógica proposicional y de predicados.', '🔣', '#818cf8', 'Lógica', null, null, false, '[{"id":"log-01","order":1,"type":"text","title":"¿Qué es la lógica y por qué razonar bien importa?","description":"La diferencia entre un argumento válido y uno que solo suena convincente.","content":"<h2>Lógica: el estudio del buen razonamiento</h2><p>La <strong>lógica</strong> es el estudio de qué hace que un argumento sea <strong>válido</strong> — es decir, que su conclusión se siga necesariamente de sus premisas, sin importar si esas premisas son verdaderas o falsas en el mundo real.</p><h2>Validez no es lo mismo que verdad</h2><div class=\"example\">🧪 <strong>Argumento válido con premisas falsas:</strong><br>Premisa 1: Todos los peces vuelan.<br>Premisa 2: Nemo es un pez.<br>Conclusión: Nemo vuela.<br>La estructura es perfectamente válida — SI las premisas fueran verdaderas, la conclusión tendría que serlo. El problema es que la premisa 1 es falsa, no la lógica del argumento.</div><h2>¿Por qué importa distinguir esto?</h2><p>Muchos argumentos que circulan en debates, noticias y redes sociales fallan en uno de estos dos lugares: o la estructura no es válida (la conclusión no se sigue realmente), o las premisas son falsas — y confundir ambos problemas hace muy difícil discutir con claridad.</p><div class=\"tip\">💡 Aprender lógica no te dice QUÉ es verdad sobre el mundo — te da las herramientas para reconocer si un argumento, sea cual sea su tema, tiene una estructura sólida o no.</div>","exercises":[{"id":"log-01-1","type":"challenge","prompt":"Encuentra un argumento válido pero con al menos una premisa falsa (como el ejemplo del pez que vuela). Escríbelo con la misma estructura (premisa 1, premisa 2, conclusión) y compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué significa que un argumento sea \"válido\" en lógica?","options":["Que su conclusión sea verdadera en la realidad","Que la conclusión se siga necesariamente de las premisas, sin importar si son verdaderas","Que sea popular o convincente","Que use palabras técnicas"],"correctIndex":1},"comments":[]},{"id":"log-02","order":2,"type":"text","title":"Lógica clásica (Aristotélica): silogismos","description":"La primera formalización sistemática del razonamiento, hace más de 2000 años.","content":"<h2>Aristóteles y el nacimiento de la lógica formal</h2><p>Alrededor del siglo IV a.C., Aristóteles fue el primero en estudiar sistemáticamente qué patrones de razonamiento garantizan una conclusión válida — este sistema se conoce como <strong>lógica clásica</strong> o aristotélica, y su herramienta central es el <strong>silogismo</strong>.</p><h2>Anatomía de un silogismo</h2><div class=\"example\">🧪 <strong>El silogismo más famoso de la historia:</strong><br>Premisa mayor: Todos los hombres son mortales.<br>Premisa menor: Sócrates es hombre.<br>Conclusión: Sócrates es mortal.<br>Dos premisas y una conclusión, conectadas por un término compartido (\"hombre\").</div><h2>Las leyes clásicas del pensamiento</h2><ul><li><strong>Ley de identidad:</strong> algo es idéntico a sí mismo (A es A).</li><li><strong>Ley de no contradicción:</strong> algo no puede ser y no ser al mismo tiempo, en el mismo sentido.</li><li><strong>Ley del tercero excluido:</strong> una proposición es verdadera o falsa, no hay una tercera opción.</li></ul><div class=\"tip\">💡 Estas tres leyes te pueden parecer obvias — y esa es precisamente su fuerza: son la base implícita de casi todo razonamiento humano, formalizada por primera vez hace más de 2000 años.</div>","exercises":[{"id":"log-02-1","type":"challenge","prompt":"Escribe tu propio silogismo válido, con premisa mayor, premisa menor y conclusión, siguiendo el ejemplo de Sócrates. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué dice la \"ley de no contradicción\"?","options":["Todo es verdadero","Algo no puede ser y no ser al mismo tiempo, en el mismo sentido","Las palabras no tienen significado fijo","Los silogismos siempre son falsos"],"correctIndex":1},"comments":[]},{"id":"log-03","order":3,"type":"text","title":"Lógica proposicional: conectores y tablas de verdad","description":"Cómo combinar afirmaciones simples en argumentos más complejos, con precisión matemática.","content":"<h2>Proposiciones: afirmaciones que son verdaderas o falsas</h2><p>Una <strong>proposición</strong> es cualquier afirmación que puede calificarse como verdadera o falsa (no una pregunta ni una orden). \"Está lloviendo\" es una proposición; \"¿está lloviendo?\" no lo es.</p><h2>Conectores lógicos</h2><ul><li><strong>Y (∧, conjunción):</strong> verdadero solo si AMBAS partes son verdaderas.</li><li><strong>O (∨, disyunción):</strong> verdadero si AL MENOS UNA parte es verdadera.</li><li><strong>NO (¬, negación):</strong> invierte el valor de verdad.</li><li><strong>SI...ENTONCES (→, condicional):</strong> falso únicamente cuando la primera parte es verdadera y la segunda es falsa.</li></ul><div class=\"example\">🧪 <strong>Tabla de verdad de \"Y\" (A ∧ B):</strong><br>V y V → V<br>V y F → F<br>F y V → F<br>F y F → F</div><div class=\"warn\">⚠️ El condicional \"→\" confunde a mucha gente: \"Si llueve, entonces me mojo\" NO es falso solo porque no llueva ese día — es falso ÚNICAMENTE si llovió y aun así no te mojaste. Si no llueve, la afirmación condicional simplemente no se pone a prueba, y se considera verdadera por default.</div><h2>Por qué esto conecta con la computación</h2><div class=\"tip\">💡 Estos mismos conectores (Y, O, NO) son exactamente los operadores lógicos que ya usaste si tomaste el curso de Fundamentos de Programación de esta academia — la lógica proposicional es literalmente el lenguaje matemático detrás de cualquier condicional en código.</div>","exercises":[{"id":"log-03-1","type":"challenge","prompt":"Construye la tabla de verdad completa (las 4 combinaciones de V/F) para el conector \"O\" (∨). Compártela con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuándo es falso el condicional \"Si A, entonces B\" (A → B)?","options":["Siempre que A sea falso","Únicamente cuando A es verdadero y B es falso","Siempre que B sea verdadero","Nunca es falso"],"correctIndex":1},"comments":[]},{"id":"log-04","order":4,"type":"text","title":"Lógica de predicados (lógica matemática)","description":"Un paso más allá de la lógica proposicional: hablar de \"todos\" y \"algunos\".","content":"<h2>La limitación de la lógica proposicional</h2><p>La lógica proposicional trata proposiciones completas como bloques (\"Sócrates es mortal\") sin poder hablar de patrones generales como \"todos los X son Y\". La <strong>lógica de predicados</strong> (también llamada lógica matemática o lógica de primer orden) resuelve esto, formalizada principalmente por Gottlob Frege a finales del siglo XIX.</p><h2>Cuantificadores</h2><ul><li><strong>Cuantificador universal (∀):</strong> \"para todo x...\" — ∀x, si x es hombre, entonces x es mortal.</li><li><strong>Cuantificador existencial (∃):</strong> \"existe al menos un x...\" — ∃x, x es un cisne negro.</li></ul><div class=\"example\">🧪 El silogismo clásico de Sócrates, en notación de predicados: <code>∀x (Hombre(x) → Mortal(x))</code>, <code>Hombre(Sócrates)</code>, por lo tanto <code>Mortal(Sócrates)</code> — la misma idea, con precisión matemática exacta sobre \"todos\" vs. \"algunos\".</h2><h2>Por qué esto es \"lógica matemática\"</h2><div class=\"tip\">💡 Esta formalización es la base matemática de disciplinas enteras: la teoría de conjuntos, gran parte de las matemáticas modernas, y — como verás en el último módulo — el diseño de circuitos digitales y lenguajes de programación se apoyan directamente en esta misma lógica de predicados.</div>","exercises":[{"id":"log-04-1","type":"challenge","prompt":"Escribe, usando cuantificadores en palabras simples (\"para todo...\" o \"existe al menos un...\"), una afirmación sobre algo de tu vida cotidiana. Compártela con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué agrega la lógica de predicados frente a la lógica proposicional?","options":["Nada nuevo, son idénticas","La capacidad de hablar de \"todos\" y \"algunos\" mediante cuantificadores","Elimina la necesidad de premisas","Solo aplica a las matemáticas, no a la lógica"],"correctIndex":1},"comments":[]},{"id":"log-05","order":5,"type":"text","title":"Falacias lógicas comunes","description":"Argumentos que PARECEN válidos pero no lo son — y cómo reconocerlos.","content":"<h2>¿Qué es una falacia?</h2><p>Una <strong>falacia lógica</strong> es un error de razonamiento que hace que un argumento parezca válido sin serlo realmente. Reconocerlas es una de las habilidades más prácticas que da estudiar lógica.</p><h2>Cinco falacias comunes</h2><ul><li><strong>Ad hominem:</strong> atacar a la persona en vez de su argumento (\"no le creas, es un mentiroso\" — no responde si el argumento es correcto o no).</li><li><strong>Falsa dicotomía:</strong> presentar solo dos opciones cuando existen más (\"o estás conmigo o estás contra mí\").</li><li><strong>Pendiente resbaladiza:</strong> afirmar que un paso pequeño llevará inevitablemente a un extremo, sin evidencia de esa cadena (\"si permitimos esto, en poco tiempo pasará lo peor imaginable\").</li><li><strong>Apelación a la autoridad:</strong> asumir que algo es verdad solo porque lo dijo alguien con prestigio, en un tema fuera de su experiencia.</li><li><strong>Espantapájaros (straw man):</strong> distorsionar el argumento del otro para que sea más fácil de atacar, en vez de responder al argumento real.</li></ul><div class=\"warn\">⚠️ Las falacias son efectivas precisamente porque a menudo SÍ producen una sensación de haber \"ganado\" el argumento — el objetivo de estudiarlas no es solo detectarlas en otros, sino evitar caer en ellas uno mismo.</div>","exercises":[{"id":"log-05-1","type":"challenge","prompt":"Identifica una falacia lógica (de las 5 vistas u otra que conozcas) en algún debate, noticia o discusión que hayas visto recientemente. Explica por qué es una falacia y compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué es un argumento \"ad hominem\"?","options":["Presentar solo dos opciones falsas","Atacar a la persona en vez de responder a su argumento","Citar una autoridad","Exagerar las consecuencias de algo"],"correctIndex":1},"comments":[]},{"id":"log-06","order":6,"type":"text","title":"De la lógica a la computación: puertas lógicas","description":"Cómo la lógica de hace 2000+ años terminó siendo la base física de toda computadora moderna.","content":"<h2>Boole: convertir la lógica en álgebra</h2><p>En el siglo XIX, George Boole demostró que la lógica proposicional podía tratarse como un sistema algebraico — con solo dos valores (verdadero/falso, o 1/0) en vez de números infinitos. A este sistema se le llama <strong>álgebra booleana</strong>, y es el puente directo entre la lógica clásica y la computación moderna.</p><h2>Puertas lógicas: lógica hecha circuito eléctrico</h2><p>Una <strong>puerta lógica</strong> es un componente electrónico diminuto que implementa físicamente un conector lógico (Y, O, NO) usando voltajes altos/bajos como 1/0 — como viste en el curso de Ingeniería Eléctrica, esto se logra con transistores actuando como interruptores.</p><div class=\"example\">🧪 Una puerta \"Y\" (AND) solo deja pasar una señal alta si AMBAS entradas son altas — exactamente la misma tabla de verdad del conector lógico \"∧\" que viste en el módulo 3, ahora implementada en silicio real.</div><h2>Cierre del curso</h2><div class=\"tip\">💡 Todo circuito digital, todo chip, todo programa que corre en cualquier computadora del mundo es, en el fondo, una cascada gigantesca de estas mismas puertas lógicas — cada una implementando, físicamente, las mismas reglas de razonamiento que Aristóteles formalizó hace más de 2000 años y que recorriste en este curso completo: validez, silogismos, conectores proposicionales, cuantificadores y falacias a evitar.</div>","exercises":[{"id":"log-06-1","type":"challenge","prompt":"Explica con tus palabras la conexión completa entre Aristóteles (hace 2000+ años) y el chip de tu celular hoy. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué hace una puerta lógica en un circuito digital?","options":["Almacena energía eléctrica","Implementa físicamente un conector lógico (Y, O, NO) usando voltajes altos/bajos","Convierte corriente alterna en directa","Mide la resistencia de un cable"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-lenguajes-programacion', 'Introducción a los Lenguajes de Programación', 'Compilados vs. interpretados, tipado, paradigmas y niveles de abstracción: cómo elegir y entender cualquier lenguaje de programación.', 'Eres el Mago, tutor de Introducción a los Lenguajes de Programación en Oliver Academy. Usa ejemplos comparativos entre lenguajes conocidos (Python, JavaScript, C, Java) para ilustrar cada concepto, y conecta con el curso de El Paradigma de Oliver Academy (React) cuando sea relevante.', '📖', '#a855f7', 'Programación', 'Lenguajes de Programación', null, false, '[{"id":"leng-01","order":1,"type":"text","title":"¿Qué es un lenguaje de programación?","description":"El puente entre cómo piensa un humano y cómo funciona un procesador.","content":"<h2>El problema que resuelven los lenguajes de programación</h2><p>Un procesador solo entiende secuencias de 1s y 0s (código máquina) — pero escribir directamente en eso es prácticamente inhumano. Un <strong>lenguaje de programación</strong> es una notación intermedia, diseñada para que los humanos puedan expresar instrucciones de forma legible, que luego se traduce a código máquina.</p><h2>Sintaxis vs. semántica</h2><p>La <strong>sintaxis</strong> son las reglas de escritura de un lenguaje (dónde van los paréntesis, los puntos y coma). La <strong>semántica</strong> es el significado real de esas instrucciones — qué hace el programa cuando se ejecuta. Dos lenguajes pueden tener sintaxis parecida y semántica muy distinta, o viceversa.</p><div class=\"tip\">💡 Aprender un primer lenguaje de programación es más difícil que aprender el segundo o el tercero, precisamente porque el primero te obliga a aprender sintaxis Y conceptos de programación (variables, bucles, funciones) al mismo tiempo — los siguientes lenguajes solo te piden aprender la sintaxis nueva sobre conceptos que ya conoces.</div>","exercises":[{"id":"leng-01-1","type":"challenge","prompt":"¿Ya conoces algún lenguaje de programación, aunque sea básico? Si no, describe con tus palabras por qué crees que hace falta un \"lenguaje intermedio\" entre humanos y procesadores. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué es la \"sintaxis\" de un lenguaje de programación?","options":["El significado real de las instrucciones","Las reglas de escritura del lenguaje","La velocidad de ejecución","El nombre del lenguaje"],"correctIndex":1},"comments":[]},{"id":"leng-02","order":2,"type":"text","title":"Compilados vs. interpretados","description":"Dos formas distintas de convertir tu código en algo que la computadora puede ejecutar.","content":"<h2>Lenguajes compilados</h2><p>En un lenguaje <strong>compilado</strong> (como C, C++ o Rust), un programa llamado <strong>compilador</strong> traduce TODO tu código a código máquina de una sola vez, ANTES de ejecutarlo, produciendo un archivo ejecutable independiente. Es más rápido en ejecución, pero cualquier error de sintaxis se detecta antes de poder correr el programa.</p><h2>Lenguajes interpretados</h2><p>En un lenguaje <strong>interpretado</strong> (como Python o JavaScript clásico), un programa llamado <strong>intérprete</strong> lee y ejecuta el código línea por línea, en el momento — sin producir un archivo ejecutable separado. Es más flexible para probar cosas rápido, pero típicamente más lento en ejecución.</p><div class=\"example\">🧪 Por eso puedes escribir una línea de JavaScript en la consola del navegador y ver el resultado al instante — se está interpretando ahí mismo, sin un paso de compilación previo.</div><h2>La línea se ha vuelto borrosa</h2><div class=\"tip\">💡 Muchos lenguajes modernos (incluido el JavaScript que corre esta misma plataforma) usan técnicas híbridas como la <strong>compilación JIT (just-in-time)</strong> — compilan partes del código mientras se ejecuta, para combinar la flexibilidad de interpretar con la velocidad de compilar. La distinción compilado/interpretado hoy es más un espectro que una frontera absoluta.</div>","exercises":[{"id":"leng-02-1","type":"challenge","prompt":"¿Prefieres la idea de \"ver el resultado al instante\" (interpretado) o \"revisar todo antes de correr nada\" (compilado)? Justifica tu preferencia y compártela con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es la diferencia central entre un lenguaje compilado y uno interpretado?","options":["Los interpretados no tienen errores","Uno traduce todo el código antes de ejecutar (compilado); el otro lo ejecuta línea por línea en el momento (interpretado)","Los compilados no se pueden usar en la web","No hay diferencia real"],"correctIndex":1},"comments":[]},{"id":"leng-03","order":3,"type":"text","title":"Tipado: estático vs. dinámico, fuerte vs. débil","description":"Cómo cada lenguaje decide cuándo (y qué tan estrictamente) verificar el tipo de un dato.","content":"<h2>Tipado estático vs. dinámico</h2><p>En el <strong>tipado estático</strong> (Java, TypeScript, C), el tipo de cada variable se decide y verifica ANTES de ejecutar el programa — muchos errores se atrapan antes de correr una sola línea. En el <strong>tipado dinámico</strong> (Python, JavaScript), el tipo se decide durante la ejecución, y una misma variable puede cambiar de tipo libremente.</p><div class=\"example\">🧪 En JavaScript (dinámico): <code>let x = 5; x = \"hola\"</code> — perfectamente válido, x cambió de número a texto. En TypeScript (estático) esto daría un error antes de ejecutar nada.</div><h2>Tipado fuerte vs. débil</h2><p>El <strong>tipado fuerte</strong> no permite mezclar tipos incompatibles sin conversión explícita. El <strong>tipado débil</strong> convierte tipos automáticamente, a veces de forma sorprendente.</p><div class=\"warn\">⚠️ El ejemplo más famoso de tipado débil \"sorprendente\": en JavaScript, <code>\"5\" + 3</code> da <code>\"53\"</code> (concatena texto), pero <code>\"5\" - 3</code> da <code>2</code> (resta números) — el mismo tipo de mezcla produce resultados de naturaleza completamente distinta según el operador.</div><h2>No hay una combinación \"correcta\"</h2><div class=\"tip\">💡 El tipado estático atrapa más errores antes de ejecutar, a cambio de más código explícito. El tipado dinámico es más rápido de escribir para prototipos, a cambio de más errores que solo aparecen en tiempo de ejecución. Ninguno es \"mejor\" en abstracto — depende del proyecto y su tamaño.</div>","exercises":[{"id":"leng-03-1","type":"challenge","prompt":"Explica con tus palabras por qué \"5\" + 3 y \"5\" - 3 dan resultados de naturaleza distinta en JavaScript, usando el concepto de tipado débil. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué caracteriza al tipado estático frente al dinámico?","options":["El tipo se verifica en tiempo de ejecución","El tipo de cada variable se decide y verifica antes de ejecutar el programa","No existen tipos en absoluto","Solo aplica a lenguajes compilados"],"correctIndex":1},"comments":[]},{"id":"leng-04","order":4,"type":"text","title":"Paradigmas de programación","description":"Distintas filosofías para organizar la lógica de un programa.","content":"<h2>Programación imperativa/procedural</h2><p>El programa es una secuencia de instrucciones paso a paso que modifican el estado de la máquina — el estilo más directo y cercano a \"cómo piensa\" una computadora (C es el ejemplo clásico).</p><h2>Programación orientada a objetos (POO)</h2><p>El programa se organiza en <strong>objetos</strong> que combinan datos y comportamiento juntos (Java, y buena parte de C++ y Python). Modela el mundo como \"cosas\" que tienen propiedades y saben hacer cosas.</p><h2>Programación funcional</h2><p>El programa se construye combinando <strong>funciones puras</strong> (mismo input, mismo output, sin efectos secundarios), evitando modificar datos existentes (Haskell es el ejemplo más puro; JavaScript y Python lo permiten como estilo).</p><div class=\"tip\">💡 Si ya tomaste el curso de El Paradigma de Oliver Academy, ya viste programación funcional en acción: React favorece funciones puras e inmutabilidad — es exactamente el paradigma funcional aplicado a construir interfaces.</div><h2>Ningún lenguaje moderno es \"puro\" en un solo paradigma</h2><div class=\"warn\">⚠️ Muchos lenguajes modernos (JavaScript, Python) son <strong>multiparadigma</strong> — permiten mezclar estilos imperativo, orientado a objetos y funcional en el mismo programa. La pregunta real no es \"¿qué paradigma usa este lenguaje?\" sino \"¿qué paradigma estoy eligiendo usar en esta parte del código?\".</div>","exercises":[{"id":"leng-04-1","type":"challenge","prompt":"De los tres paradigmas (imperativo, orientado a objetos, funcional), ¿cuál te parece más intuitivo para pensar un problema? Da un ejemplo simple de tu vida cotidiana modelado con ese paradigma. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué caracteriza a la programación funcional?","options":["Modificar variables globales libremente","Combinar funciones puras, evitando modificar datos existentes","Organizar todo en objetos con propiedades","Ejecutar instrucciones en cualquier orden aleatorio"],"correctIndex":1},"comments":[]},{"id":"leng-05","order":5,"type":"text","title":"Niveles de abstracción: de ensamblador a Python","description":"Qué tan \"cerca\" o \"lejos\" está un lenguaje del hardware real.","content":"<h2>Bajo nivel: control total, más esfuerzo</h2><p>Un lenguaje de <strong>bajo nivel</strong> (ensamblador) trabaja casi directamente con las instrucciones que el procesador entiende — control total sobre la memoria y el hardware, a cambio de mucho más código y esfuerzo para tareas simples.</p><h2>Nivel medio: control con algo de comodidad</h2><p><strong>C</strong> se considera de \"nivel medio\" — da acceso directo a memoria (punteros) pero con una sintaxis mucho más manejable que ensamblador. Se usa para sistemas operativos, drivers, y software donde el rendimiento es crítico.</p><h2>Alto nivel: comodidad, menos control directo</h2><p>Lenguajes de <strong>alto nivel</strong> (Python, JavaScript, Ruby) se alejan del hardware casi por completo — manejan memoria automáticamente (recolección de basura), tienen estructuras de datos incorporadas, y priorizan la legibilidad y velocidad de escritura sobre el control fino.</p><div class=\"example\">🧪 Sumar dos números en ensamblador puede tomar varias líneas manipulando registros específicos del procesador. En Python es literalmente <code>a + b</code>. Ambos terminan ejecutando instrucciones parecidas por debajo — la diferencia es cuánto de ese trabajo hace el lenguaje por ti.</div><div class=\"tip\">💡 A mayor nivel de abstracción, generalmente menos control directo sobre el hardware, pero mucha más velocidad para escribir y entender el código — es un intercambio, no una escalera donde \"más alto\" siempre es \"mejor\".</div>","exercises":[{"id":"leng-05-1","type":"challenge","prompt":"Explica con un ejemplo propio por qué \"más alto nivel\" no significa automáticamente \"mejor lenguaje\" — piensa en cuándo SÍ importaría tener control directo sobre el hardware. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué caracteriza a un lenguaje de \"alto nivel\" como Python, frente a uno de bajo nivel?","options":["Da control total y directo sobre la memoria del procesador","Se aleja del hardware, maneja memoria automáticamente y prioriza legibilidad","Solo se puede usar para sistemas operativos","Es siempre más rápido en ejecución"],"correctIndex":1},"comments":[]},{"id":"leng-06","order":6,"type":"text","title":"Cómo elegir tu primer (o siguiente) lenguaje","description":"No existe \"el mejor lenguaje\" — existe el lenguaje correcto para lo que quieres construir.","content":"<h2>La pregunta equivocada</h2><p>\"¿Cuál es el mejor lenguaje de programación?\" es, casi siempre, la pregunta equivocada — es como preguntar \"¿cuál es la mejor herramienta?\" sin decir para qué trabajo. La pregunta correcta es \"¿qué quiero construir, y qué lenguaje es común/adecuado para eso?\".</p><h2>Guías generales (no reglas absolutas)</h2><ul><li><strong>Sitios y apps web:</strong> JavaScript (y TypeScript) son casi ineludibles — corren tanto en el navegador como en el servidor.</li><li><strong>Ciencia de datos e IA:</strong> Python domina, por su ecosistema de librerías (no por ser técnicamente superior a otros).</li><li><strong>Sistemas operativos, videojuegos de alto rendimiento:</strong> C y C++ siguen siendo dominantes por su control cercano al hardware.</li><li><strong>Apps móviles nativas:</strong> Swift (iOS) y Kotlin (Android).</li></ul><div class=\"tip\">💡 Esta misma plataforma (Oliver Academy) está escrita en JavaScript (React) — precisamente porque el objetivo era construir una aplicación web interactiva, el caso de uso donde ese lenguaje es la elección natural.</div><h2>Cierre del curso</h2><div class=\"warn\">⚠️ El error más común de un principiante es paralizarse eligiendo \"el lenguaje perfecto\" antes de empezar. Los conceptos fundamentales (variables, condicionales, bucles, funciones — como viste en Fundamentos de Programación) se transfieren casi por completo entre lenguajes. El primer lenguaje que elijas importa mucho menos de lo que parece; lo que sí importa es empezar.</div>","exercises":[{"id":"leng-06-1","type":"challenge","prompt":"¿Qué te gustaría construir algún día (una app, un juego, un sitio web, un análisis de datos)? Según lo visto en este módulo, ¿qué lenguaje sería una elección razonable para eso? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"Según este módulo, ¿cuál es el error más común de un principiante al elegir su primer lenguaje?","options":["Elegir Python en vez de JavaScript","Paralizarse buscando \"el lenguaje perfecto\" en vez de simplemente empezar","No aprender ensamblador primero","Elegir un lenguaje compilado"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-historia-programacion', 'Historia de la Programación: De Ada Lovelace a la IA', 'Un recorrido cronológico completo: desde el primer algoritmo publicado en 1843 hasta la inteligencia artificial generativa de hoy.', 'Eres el Mago Ancestral, tutor de Historia de la Programación en Oliver Academy. Cuenta cada etapa como una historia con personajes reales, conectando siempre "qué problema estaba resolviendo esa generación" con la siguiente. Sé narrativo pero preciso con las fechas.', '🕰️', '#f59e0b', 'Programación', 'Historia de la Programación', null, false, '[{"id":"hprog-01","order":1,"type":"text","title":"Antes de las computadoras: Ada Lovelace (1843)","description":"El primer algoritmo de la historia se escribió casi un siglo antes de que existiera una computadora capaz de ejecutarlo.","content":"<h2>La máquina que nunca se terminó de construir</h2><p>En la Inglaterra del siglo XIX, Charles Babbage diseñó la <strong>Máquina Analítica</strong>, una computadora mecánica programable — nunca llegó a construirse completa en su época, por limitaciones de la tecnología de fabricación disponible entonces.</p><h2>Ada Lovelace: el primer algoritmo publicado</h2><p><strong>Ada Lovelace</strong>, matemática e hija del poeta Lord Byron, tradujo y anotó un artículo sobre la Máquina Analítica — sus notas incluían un método detallado, paso a paso, para que la máquina calculara los números de Bernoulli. Eso se considera el <strong>primer algoritmo de programación publicado de la historia</strong>, escrito para una máquina que nunca llegó a existir en vida de ambos.</p><div class=\"tip\">💡 Ada Lovelace también fue la primera en observar que estas máquinas podrían, en teoría, manipular cualquier tipo de símbolo (no solo números) — una idea asombrosamente adelantada a su tiempo, que anticipa cómo las computadoras modernas procesan texto, imágenes y sonido, no solo cálculos matemáticos.</div><div class=\"example\">🧪 El lenguaje de programación \"Ada\", usado hoy en sistemas críticos de aviación y defensa, lleva su nombre en honor a esta contribución.</div>","exercises":[{"id":"hprog-01-1","type":"challenge","prompt":"¿Por qué crees que se considera a Ada Lovelace \"la primera programadora de la historia\" aunque la máquina para la que escribió su algoritmo nunca se terminó de construir? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué logró Ada Lovelace en 1843, considerado el primer algoritmo publicado de la historia?","options":["Construyó la primera computadora electrónica","Escribió un método paso a paso para que la Máquina Analítica calculara los números de Bernoulli","Inventó el lenguaje Python","Diseñó el primer microchip"],"correctIndex":1},"comments":[]},{"id":"hprog-02","order":2,"type":"text","title":"Turing y la Segunda Guerra Mundial (1936-1945)","description":"La base teórica de toda computación moderna, y su primer uso real: romper códigos secretos.","content":"<h2>La Máquina de Turing: qué significa \"computar\", en teoría</h2><p>En 1936, el matemático británico <strong>Alan Turing</strong> publicó un modelo teórico abstracto — la \"Máquina de Turing\" — que define, matemáticamente, qué significa que algo sea \"computable\". Este trabajo, sin usar aún ninguna computadora física, sigue siendo la base teórica de la informática moderna.</p><h2>Bletchley Park: la teoría se vuelve práctica urgente</h2><p>Durante la Segunda Guerra Mundial, Turing lideró un equipo en Bletchley Park (Reino Unido) que construyó máquinas electromecánicas para descifrar los mensajes cifrados con la máquina alemana Enigma. Se estima que este trabajo acortó la guerra significativamente y salvó millones de vidas.</p><div class=\"warn\">⚠️ El trabajo de Turing permaneció en secreto oficial durante décadas después de la guerra — su contribución completa no se reconoció públicamente sino hasta mucho después de su muerte en 1954.</div><div class=\"tip\">💡 El \"Test de Turing\", una prueba que propuso en 1950 para evaluar si una máquina puede exhibir comportamiento inteligente indistinguible de un humano, sigue siendo una referencia central en las conversaciones sobre inteligencia artificial casi 75 años después.</div>","exercises":[{"id":"hprog-02-1","type":"challenge","prompt":"¿Qué relación encuentras entre el trabajo teórico de Turing (1936, sin computadoras físicas) y su aplicación práctica urgente unos años después (Bletchley Park)? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Para qué se usaron las máquinas de descifrado que lideró Alan Turing en Bletchley Park?","options":["Para jugar ajedrez","Para descifrar los mensajes cifrados de la máquina alemana Enigma durante la Segunda Guerra Mundial","Para calcular impuestos","Para crear el primer lenguaje de programación"],"correctIndex":1},"comments":[]},{"id":"hprog-03","order":3,"type":"text","title":"Las primeras computadoras y lenguajes (1940s-1950s)","description":"De cablear físicamente una máquina a escribir instrucciones en texto.","content":"<h2>ENIAC: programar reconectando cables</h2><p>La <strong>ENIAC</strong> (1945), una de las primeras computadoras electrónicas de propósito general, no se \"programaba\" escribiendo texto — se reconfiguraba físicamente moviendo cables e interruptores, un proceso que podía tomar días para cada nuevo cálculo.</p><h2>El primer paso hacia el software: lenguaje ensamblador</h2><p>Pronto se desarrollaron formas de escribir instrucciones como texto simbólico (en vez de números binarios directos o cableado físico) que un programa simple traducía a código máquina — el nacimiento del <strong>lenguaje ensamblador</strong>.</p><h2>FORTRAN (1957) y COBOL (1959): los primeros lenguajes de alto nivel</h2><p><strong>FORTRAN</strong> (\"Formula Translation\"), creado por un equipo liderado por John Backus en IBM, permitió escribir fórmulas matemáticas casi como se escriben en papel — un salto enorme en productividad para cálculo científico. <strong>COBOL</strong>, orientado a negocios, buscaba ser legible casi como inglés simple, para que gerentes no técnicos pudieran entender el código.</p><div class=\"tip\">💡 Sorprendentemente, versiones modernas de COBOL siguen corriendo hoy en día en sistemas bancarios y gubernamentales de todo el mundo — código escrito hace más de 60 años, todavía en producción.</div>","exercises":[{"id":"hprog-03-1","type":"challenge","prompt":"¿Qué te parece más sorprendente: que programar la ENIAC significara mover cables físicamente, o que código COBOL de hace 60+ años siga funcionando en bancos hoy? Explica por qué y compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cómo se \"programaba\" la ENIAC, antes de los lenguajes de programación de texto?","options":["Escribiendo código en Python","Reconectando físicamente cables e interruptores","Con comandos de voz","No se podía programar, solo hacía un cálculo fijo"],"correctIndex":1},"comments":[]},{"id":"hprog-04","order":4,"type":"text","title":"C y Unix: la revolución de los 70","description":"El lenguaje y el sistema operativo que todavía dan forma a casi toda la tecnología actual.","content":"<h2>El problema antes de C</h2><p>Para 1970, escribir sistemas operativos requería lenguaje ensamblador específico de cada tipo de procesador — un sistema operativo no se podía \"mover\" fácilmente de una máquina a otra sin reescribirlo casi por completo.</p><h2>C: portabilidad y control, juntos</h2><p>Dennis Ritchie, en los Laboratorios Bell, creó el lenguaje <strong>C</strong> (1972) — suficientemente cercano al hardware para tener control fino (como el ensamblador), pero portable entre distintos tipos de computadora sin reescribir todo.</p><h2>Unix: un sistema operativo escrito en su propio lenguaje</h2><p>Ken Thompson y Dennis Ritchie reescribieron el sistema operativo <strong>Unix</strong> en C — esto significaba que Unix podía llevarse a cualquier computadora nueva con relativamente poco esfuerzo, algo revolucionario para la época.</p><div class=\"tip\">💡 El legado de C y Unix es casi incalculable: Linux (que corre la mayoría de los servidores de internet), macOS, Android, y los lenguajes C++, Java y JavaScript heredan ideas directas de este linaje. Cuando escribes <code>if (x == 5) { ... }</code> en casi cualquier lenguaje moderno, estás usando una sintaxis que C popularizó hace más de 50 años.</div>","exercises":[{"id":"hprog-04-1","type":"challenge","prompt":"¿Reconoces la sintaxis de \"if (condición) { ... }\" en algún lenguaje que hayas visto? Investiga (o recuerda) si viene de la tradición de C. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Por qué fue revolucionario escribir el sistema operativo Unix en el lenguaje C?","options":["Porque hizo Unix más lento","Porque permitió llevar Unix a computadoras distintas con relativamente poco esfuerzo, en vez de reescribirlo en ensamblador cada vez","Porque eliminó la necesidad de sistemas operativos","Porque C solo funciona en una máquina específica"],"correctIndex":1},"comments":[]},{"id":"hprog-05","order":5,"type":"text","title":"Computadoras personales y objetos (1980s-1990s)","description":"La programación sale de los laboratorios y llega a millones de hogares.","content":"<h2>La computadora personal cambia quién programa</h2><p>Con el auge de computadoras personales (Apple II, IBM PC, Commodore 64) en los 80, programar dejó de ser exclusivo de universidades y corporaciones — millones de personas tuvieron acceso a una computadora en casa, muchas aprendiendo a programar en <strong>BASIC</strong>, un lenguaje diseñado deliberadamente para ser fácil de aprender.</p><h2>C++ y la programación orientada a objetos se popularizan</h2><p>Bjarne Stroustrup extendió C agregándole conceptos de programación orientada a objetos, creando <strong>C++</strong> (1985) — permitía organizar programas grandes en \"objetos\" con datos y comportamiento juntos, más manejable que código puramente procedural para sistemas complejos.</p><h2>Java (1995): \"escribe una vez, corre en cualquier lado\"</h2><p><strong>Java</strong>, creado por Sun Microsystems, prometía que un mismo programa pudiera correr sin cambios en cualquier sistema operativo, gracias a una \"máquina virtual\" intermedia — una promesa muy atractiva para empresas hartas de reescribir software para cada plataforma.</p><div class=\"tip\">💡 Esta era estableció la programación orientada a objetos como el paradigma dominante en la industria durante casi dos décadas — la base de la mayoría del software empresarial que todavía corre hoy.</div>","exercises":[{"id":"hprog-05-1","type":"challenge","prompt":"¿Por qué crees que la promesa de Java (\"escribe una vez, corre en cualquier lado\") era tan atractiva para las empresas de los 90? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué hizo posible que las computadoras personales de los 80 popularizaran la programación?","options":["Solo las usaban científicos","Millones de personas tuvieron acceso a una computadora en casa por primera vez","Eliminaron la necesidad de aprender a programar","Solo funcionaban con lenguaje ensamblador"],"correctIndex":1},"comments":[]},{"id":"hprog-06","order":6,"type":"text","title":"Internet y los lenguajes web (1990s-2000s)","description":"Cuando programar dejó de ser solo para una computadora y empezó a ser para el mundo entero, conectado.","content":"<h2>JavaScript: creado en 10 días para un problema urgente</h2><p>En 1995, Brendan Eich creó <strong>JavaScript</strong> en apenas diez días para Netscape, con el objetivo de hacer que las páginas web pudieran reaccionar sin recargar por completo cada vez. Décadas después, es uno de los lenguajes más usados del planeta — y el mismo que corre esta plataforma completa, tanto en tu navegador como potencialmente en el servidor (Node.js).</p><h2>Python: legibilidad como prioridad</h2><p>Guido van Rossum había creado <strong>Python</strong> ya en 1991, priorizando explícitamente que el código fuera fácil de leer, casi como pseudocódigo real — una filosofía de diseño que décadas después lo volvió el lenguaje dominante en ciencia de datos e inteligencia artificial.</p><h2>PHP y el auge de la web dinámica</h2><p><strong>PHP</strong>, creado por Rasmus Lerdorf, se especializó en generar páginas web dinámicamente desde un servidor — impulsando sitios como los primeros foros, blogs y tiendas en línea de la era de internet masivo.</p><div class=\"tip\">💡 Nota algo curioso: los tres lenguajes de esta era (JavaScript, Python, PHP) fueron diseñados originalmente como soluciones rápidas y pragmáticas a problemas concretos, no como proyectos académicos perfectamente planeados — y aun así se volvieron algunos de los lenguajes más influyentes de la historia.</div>","exercises":[{"id":"hprog-06-1","type":"challenge","prompt":"¿Te sorprende que JavaScript se haya creado en solo 10 días y hoy sea uno de los lenguajes más usados del mundo? ¿Qué crees que explica ese éxito a pesar de su origen apresurado? Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Con qué objetivo original se creó JavaScript en 1995?","options":["Para ciencia de datos avanzada","Para que las páginas web pudieran reaccionar sin recargar por completo","Para sistemas operativos","Para reemplazar a C++"],"correctIndex":1},"comments":[]},{"id":"hprog-07","order":7,"type":"text","title":"La era moderna: código abierto, la nube y la IA (2010s-hoy)","description":"Cómo llegamos del primer algoritmo de 1843 a escribir código junto a una inteligencia artificial.","content":"<h2>Código abierto: construir en público, entre desconocidos</h2><p>Plataformas como GitHub (fundada en 2008) hicieron que colaborar en proyectos de <strong>código abierto</strong> —software cuyo código es público y cualquiera puede contribuir— se volviera masivo. Gran parte de la infraestructura de internet moderna (Linux, la mayoría de los lenguajes y librerías que usas) es código abierto, mantenido por comunidades globales de voluntarios y empresas juntas.</p><h2>La nube: alquilar computadoras en vez de comprarlas</h2><p>Servicios como AWS, Google Cloud y Supabase (el que usa esta misma plataforma) permitieron que cualquier persona pudiera \"rentar\" infraestructura de servidores de nivel empresarial por unos dólares al mes, en vez de comprar y mantener hardware propio — democratizando quién puede construir y lanzar una aplicación real.</p><h2>IA generativa: escribir código junto a un modelo de lenguaje</h2><p>Desde principios de la década de 2020, modelos de lenguaje como los de la familia Claude pueden generar, explicar y corregir código en conversación directa con un programador — cambiando otra vez, como en cada etapa anterior de esta historia, qué significa \"programar\" en la práctica diaria.</p><div class=\"tip\">💡 Cierre del curso: desde el algoritmo en papel de Ada Lovelace (1843) para una máquina que nunca existió, hasta escribir código hoy junto a una IA conversacional, cada etapa de esta historia resolvió el problema urgente de su momento — y sentó, sin saberlo casi siempre, las bases exactas de la siguiente. Esta misma plataforma en la que estás aprendiendo es, literalmente, el punto más reciente de esa cadena de casi 200 años.</div>","exercises":[{"id":"hprog-07-1","type":"challenge","prompt":"De todo el recorrido histórico de este curso (Ada Lovelace, Turing, C/Unix, computadoras personales, internet, y ahora IA), ¿qué etapa te parece la más sorprendente o la que menos conocías? Explica por qué y compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"Según el cierre de este curso, ¿qué patrón se repite en cada etapa de la historia de la programación?","options":["Cada etapa ignora por completo a la anterior","Cada etapa resuelve el problema urgente de su momento y sienta las bases de la siguiente","La programación no ha cambiado desde 1843","Solo importan los últimos 10 años"],"correctIndex":1},"comments":[]}]'::jsonb)
